\begin{aligned}
\delta W^{\text{ nc}} &= \vec{F}^\text{ nc} \cdot \left( \frac{\partial \, \vec{r}^{\text{ nc}}}{\partial \theta} \right) \delta \theta = Q_{\theta} \delta \theta\\
&= - b (R_2 \dot{\theta}) R_2 \delta \theta\\
&= - b \, R_2 ^2 \, \dot{\theta} \delta \theta
\end{aligned}
